solution.solution.rs:
use std::marker::PhantomData;

struct Closed;
struct Open;
struct Authenticated;

trait CanClose {}
impl CanClose for Open {}
impl CanClose for Authenticated {}

struct Connection<S> {
    log: Vec<String>,
    state: PhantomData<S>,
}

impl<S> Connection<S> {
    fn log(&self) -> &[String] {
        &self.log
    }

    fn into_state<T>(mut self, entry: String) -> Connection<T> {
        self.log.push(entry);
        Connection { log: self.log, state: PhantomData }
    }
}

impl Connection<Closed> {
    fn new(host: &str) -> Connection<Closed> {
        Connection { log: vec![format!("created {host}")], state: PhantomData }
    }

    fn open(self) -> Connection<Open> {
        self.into_state("opened".to_string())
    }
}

impl Connection<Open> {
    fn login(mut self, user: &str, password: &str) -> Result<Connection<Authenticated>, Connection<Open>> {
        if password == "secret" {
            Ok(self.into_state(format!("logged in as {user}")))
        } else {
            self.log.push("login failed".to_string());
            Err(self)
        }
    }
}

impl Connection<Authenticated> {
    fn send(&mut self, message: &str) {
        self.log.push(format!("sent {message}"));
    }
}

impl<S: CanClose> Connection<S> {
    fn close(self) -> Connection<Closed> {
        self.into_state("closed".to_string())
    }
}

unitTests:
test("the happy path", || {
    let open = Connection::new("db.local").open();
    let mut session = match open.login("ada", "secret") {
        Ok(s) => s,
        Err(_) => panic!("login should work"),
    };
    session.send("hello");
    session.send("bye");
    let closed = session.close();
    check_eq(closed.log().to_vec(), vec!["created db.local", "opened", "logged in as ada", "sent hello", "sent bye", "closed"]);
});

test("a failed login gives the connection back", || {
    let open = Connection::new("x").open();
    let open = match open.login("ada", "wrong") {
        Ok(_) => panic!("wrong password accepted"),
        Err(back) => back,
    };
    let closed = open.close();
    check_eq(closed.log().to_vec(), vec!["created x", "opened", "login failed", "closed"]);
});

